from ub import *
UNIT = talk_unit("u178",
 ["membalas percakapan **di tempat kerja**",
  "**meminta dan menawarkan bantuan** rekan",
  "memberi **laporan singkat** tentang pekerjaan",
  "menyetujui, menunda, dan menolak permintaan secara profesional"],
 "Di tempat kerja, jawaban yang singkat, sopan, dan jelas lebih dihargai. Latih balasan untuk rapat singkat, permintaan tolong, dan laporan.",
 [("Meminta bantuan", "Could you give me a hand with ...?"), ("Menawarkan bantuan", "Would you like me to ...?"), ("Melaporkan progres", "I've finished ... / I'm working on ..."), ("Menunda", "I'll get back to you by ..."), ("Menyampaikan masalah", "There's a problem with ..."), ("Menutup rapat", "Thank you, everyone. That's all for today.")],
 "Dialog: Meminta bantuan",
 [("Ms. Sari", "Mr. Adi, could you give me a hand with this report?", "Pak Adi, bisa bantu saya dengan laporan ini?"), ("Mr. Adi", "Of course. What do you need?", "Tentu. Apa yang Anda butuhkan?"), ("Ms. Sari", "I need the sales figures for May.", "Saya butuh angka penjualan bulan Mei."), ("Mr. Adi", "I'll send them to you this afternoon.", "Saya akan kirim sore ini.")],
 [("Rekan meminta bantuan.", "Colleague: Could you give me a hand with this file?", "Setuju membantu.", "Sure, what do you need? // Of course. Let me take a look. // Yes, no problem.", "sure,course,yes,help"),
  ("Atasan menanyakan laporan.", "Manager: How is the report going?", "Katakan sudah 80 persen selesai.", "It's about eighty percent done. // I've almost finished. I just need the final numbers. // It's going well. I'll finish it today.", "percent,finished,done,going"),
  ("Atasan menanyakan kapan selesai.", "Manager: When can you send it to me?", "Janji mengirim sebelum pukul lima.", "I'll send it before five o'clock. // By five this afternoon. // I can send it by five.", "five,by,before"),
  ("Rekan meminta data yang belum kamu punya.", "Colleague: Do you have the customer list?", "Katakan kamu akan menghubunginya kembali.", "Not yet. I'll get back to you soon. // I don't have it now, but I'll find it. // Let me check and get back to you.", "back,check,find,soon"),
  ("Ada masalah teknis.", "IT: What seems to be the problem?", "Katakan komputermu tidak mau menyala.", "My computer won't start. // The computer doesn't turn on. // There's a problem with my computer.", "computer,start,turn,problem"),
  ("Atasan memberi tugas baru.", "Manager: Can you take on this project?", "Terima dan tanya tenggatnya.", "Sure. When is the deadline? // Yes, I'd be happy to. What's the deadline? // OK, I'll do it. When do you need it?", "deadline,when"),
  ("Rekan menawarkan bantuan.", "Colleague: Would you like me to take notes?", "Terima dengan terima kasih.", "Yes, please. Thank you! // That would be great, thanks. // Thanks, that would help.", "yes,thank,great,help"),
  ("Menolak karena sibuk.", "Colleague: Can you join the meeting at four?", "Tolak sopan karena ada tenggat.", "I'm sorry, I have a deadline at four. // Sorry, I can't. I'm busy then. // I'm afraid I can't. Can I join later?", "sorry,afraid,can't,busy,deadline"),
  ("Rapat dimulai.", "Manager: Let's begin the meeting.", "Katakan kamu siap dan membawa laporan.", "I'm ready, and I have the report. // Ready. I've brought the report. // OK, I have my report with me.", "ready,report,brought"),
  ("Menyetujui rencana.", "Manager: I suggest we start next Monday.", "Setujui.", "That sounds good to me. // I agree. Monday is fine. // Yes, that works.", "good,agree,fine,works"),
  ("Tidak setuju secara sopan.", "Manager: We should cut the budget by half.", "Sampaikan kekhawatiran.", "I'm not sure that is a good idea. // I'm worried that is too much. // Could we discuss other options?", "not,sure,worried,discuss,options"),
  ("Telepon kantor.", "Caller: Is Mr. Adi there?", "Katakan dia sedang rapat dan tawarkan menyampaikan pesan.", "He's in a meeting. Can I take a message? // Sorry, he's in a meeting. Would you like to leave a message? // He's busy right now. Can I help?", "meeting,message,busy"),
  ("Pulang kerja.", "Colleague: I'm leaving now.", "Ucapkan sampai besok.", "OK, see you tomorrow! // Have a good evening! See you. // Take care, see you tomorrow.", "see,tomorrow,evening,care"),
  ("Menyampaikan terima kasih kepada rekan.", "Colleague: Here is the file.", "Ucapkan terima kasih.", "Thank you so much. // Thanks for your help. // Thank you, that's very helpful.", "thank,thanks,helpful")],
 [('Pilih balasan yang profesional untuk "Could you give me a hand?"', "Sure, what do you need?", "No way, I am too busy to help you with that today.", "I do not care about your file, so ask someone else.", "Ask somebody else, please; I do not have time at all.", 'Menyetujui.'),
  ('Pilih ungkapan untuk menunda dengan sopan:', "I'll get back to you soon.", "Never mind, I will not be able to help you with that.", "I forgot about it, so please ask someone else instead.", "Do not ask me again about this matter, please.", 'Menunda.'),
  ('Pilih ungkapan untuk menolak dengan sopan:', "I'm afraid I can't join. I have a deadline.", "I do not want to join because that meeting sounds boring.", "That is not my job, so please find another person to join.", "No time for you today, and I will not join anyway.", 'Menolak.'),
  ('Pilih ungkapan melaporkan progres:', "I've finished the first part and I'm working on the second.", "I did something yesterday, and I will do something else later.", "Maybe I will finish it, but I am not sure about the time.", "It is somewhere on my desk, and I will find it later.", 'Progres.'),
  ('Pilih ungkapan menutup rapat:', "Thank you, everyone. That's all for today.", "Bye, everyone; the meeting was long and quite boring today.", "We are finished now, so you may all go home immediately.", "Stop talking now, because the time for the meeting is over.", 'Menutup.'),
  ('Pilih balasan pesan telepon yang baik:', "He's in a meeting. Can I take a message?", "He does not want to talk to anyone at the moment, sorry.", "Please call again later because I do not know where he is.", "I do not know him, so I cannot help you with this.", 'Pesan telepon.')],
 "Latih tiga kalimat andalan: *I'll get back to you by ...*, *Could you give me a hand with ...?*, dan *I'm afraid I can't ... because ...*.")
